```jsx
import React, { useState, useEffect } from 'react';
import axios from 'axios';

export default function WelcomeFlow({ onComplete }) {
  const [stage, setStage] = useState('greeting');
  const [messages, setMessages] = useState([]);
  const [conversation, setConversation] = useState([]);
  const [personality, setPersonality] = useState(null);
  const [goal, setGoal] = useState(null);
  const [userInput, setUserInput] = useState('');
  const [loading, setLoading] = useState(false);

  // Initialize welcome
  useEffect(() => {
    if (stage === 'greeting') {
      setConversation([
        {
          speaker: 'bot',
          message: 'Hey there! 👋 Welcome to CodePath!',
          delay: 0
        },
        {
          speaker: 'bot',
          message: "I'm so excited you're here to learn coding!",
          delay: 1
        },
        {
          speaker: 'bot',
          message: "What's your name?",
          delay: 2
        }
      ]);
    }
  }, [stage]);

  // Fetch next stage from backend
  const handleNext = async (response) => {
    setLoading(true);
    try {
      const res = await axios.post('/api/onboarding/next-stage', {
        stage,
        response
      });

      if (res.data.stage === 'complete') {
        await axios.post('/api/onboarding/save-state', {
          personality,
          goal
        });
        onComplete({ personality, goal });
      } else {
        setStage(res.data.stage);
        setConversation([]);

        // Add messages with delays
        res.data.messages.forEach((msg, idx) => {
          setTimeout(() => {
            setConversation(prev => [...prev, {
              speaker: 'bot',
              message: msg
            }]);
          }, idx * 800);
        });
      }
    } catch (error) {
      console.error('Error:', error);
    }
    setLoading(false);
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-purple-900 via-blue-900 to-indigo-900 flex items-center justify-center p-4">
      <div className="bg-white rounded-2xl shadow-2xl max-w-2xl w-full p-8">
        {/* Conversation Flow */}
        <div className="space-y-6">
          {conversation.map((msg, idx) => (
            <div
              key={idx}
              className={`flex ${msg.speaker === 'bot' ? 'justify-start' : 'justify-end'} animate-fade-in`}
            >
              <div
                className={`max-w-xs px-6 py-3 rounded-lg ${
                  msg.speaker === 'bot'
                    ? 'bg-blue-100 text-blue-900'
                    : 'bg-green-100 text-green-900'
                }`}
              >
                {msg.message}
              </div>
            </div>
          ))}
        </div>

        {/* Input/Options Area */}
        <div className="mt-8 space-y-4">
          {stage === 'greeting' && (
            <input
              type="text"
              placeholder="Type your name..."
              value={userInput}
              onChange={(e) => setUserInput(e.target.value)}
              onKeyPress={(e) => {
                if (e.key === 'Enter' && userInput.trim()) {
                  handleNext(userInput);
                  setUserInput('');
                }
              }}
              className="w-full px-4 py-2 border rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
            />
          )}

          {stage === 'personality' && (
            <div className="space-y-3">
              {['Quick & Practical', 'Deep & Theoretical'].map(opt => (
                <button
                  key={opt}
                  onClick={() => {
                    setPersonality(opt);
                    handleNext(opt);
                  }}
                  className="w-full px-4 py-3 bg-blue-500 text-white rounded-lg hover:bg-blue-600 transition"
                >
                  {opt}
                </button>
              ))}
            </div>
          )}

          {stage === 'goal' && (
            <div className="space-y-3">
              {['Career', 'Interview', 'Hobby', 'College'].map(opt => (
                <button
                  key={opt}
                  onClick={() => {
                    setGoal(opt);
                    handleNext(opt);
                  }}
                  className="w-full px-4 py-3 bg-green-500 text-white rounded-lg hover:bg-green-600 transition"
                >
                  {opt}
                </button>
              ))}
            </div>
          )}
        </div>
      </div>
    </div>
  );
}
