const express = require('express');
const router = express.Router();
const AnalyticsService = require('../services/analyticsService');
const authMiddleware = require('../middleware/auth');

// Get global leaderboard
router.get('/', (req, res) => {
  try {
    const limit = req.query.limit || 50;
    const leaderboard = AnalyticsService.calculateLeaderboard(parseInt(limit));
    res.json(leaderboard);
  } catch (error) {
    res.status(500).json({ error: error.message });
  }
});

// Get user's rank and nearby competitors
router.get('/me', authMiddleware, (req, res) => {
  try {
    const leaderboard = AnalyticsService.calculateLeaderboard(1000);
    const userEntry = leaderboard.find(entry => entry.userId === req.user.id);

    if (!userEntry) {
      return res.json({ rank: null, entry: null, nearby: [] });
    }

    const nearbyIndex = leaderboard.findIndex(entry => entry.userId === req.user.id);
    const nearby = leaderboard.slice(
      Math.max(0, nearbyIndex - 2),
      Math.min(leaderboard.length, nearbyIndex + 3)
    );

    res.json({
      rank: userEntry.rank,
      entry: userEntry,
      nearby
    });
  } catch (error) {
    res.status(500).json({ error: error.message });
  }
});

// Get user's struggling concepts
