        if not os.getenv('ANTHROPIC_API_KEY'):
            return jsonify({
                'issues': [
                    {'severity': 'low', 'message': 'Consider adding comments'},
                    {'severity': 'low', 'message': 'Improve variable naming'}
                ],
                'score': 7
            })

        response = client.messages.create(
            model="claude-3-5-sonnet-20241022",
