const express = require('express');
const router = express.Router();
const { getStore } = require('../db/store');
const authMiddleware = require('../middleware/auth');

// Get user's complete dashboard stats
router.get('/me', authMiddleware, (req, res) => {
  try {
    const store = getStore();
    const userId = req.user.id;

    // Get all progress records
    const userProgress = store.progress?.filter(p => p.userId === userId) || [];

    // Get all quiz attempts
    const quizAttempts = store.quizAttempts?.filter(q => q.userId === userId) || [];

    // Get certificates
    const certificates = store.certificates?.filter(c => c.userId === userId) || [];

    // Calculate stats
    const stats = {
      totalLanguages: userProgress.length,
      completedModules: userProgress.reduce((sum, p) => sum + (p.completedModuleIds?.length || 0), 0),
      quizzesTaken: quizAttempts.length,
      averageScore: quizAttempts.length > 0 
        ? Math.round(quizAttempts.filter(q => q.score !== null).reduce((sum, q) => sum + q.score, 0) / quizAttempts.filter(q => q.score !== null).length)
        : 0,
      certificatesEarned: certificates.length,
      streak: calculateStreak(store.analytics, userId),
      lastActive: getLastActive(quizAttempts),
      progressByLanguage: userProgress.map(p => ({
        languageId: p.languageId,
        completedModules: p.completedModuleIds?.length || 0,
        status: p.status,
        languageName: store.languages?.find(l => l.id === p.languageId)?.name
      }))
    };

    res.json(stats);
  } catch (error) {
    res.status(500).json({ error: error.message });
  }
});

function calculateStreak(analytics, userId) {
  if (!analytics) return 0;
  const userActivities = analytics.filter(a => a.userId === userId).sort((a, b) => new Date(b.date) - new Date(a.date));

  let streak = 0;
  let currentDate = new Date();

  for (let activity of userActivities) {
    const activityDate = new Date(activity.date);
    const daysDiff = Math.floor((currentDate - activityDate) / (1000 * 60 * 60 * 24));

    if (daysDiff === streak) {
      streak++;
      currentDate = activityDate;
    } else {
      break;
    }
  }

  return streak;
}

function getLastActive(quizAttempts) {
  if (quizAttempts.length === 0) return null;
  return new Date(Math.max(...quizAttempts.map(q => new Date(q.submittedAt || q.generatedAt)))).toISOString();
}

// Get detailed progress for a language
router.get('/language/:languageId', authMiddleware, (req, res) => {
  try {
    const { languageId } = req.params;
    const store = getStore();
    const userId = req.user.id;

    const progress = store.progress?.find(p => p.userId === userId && p.languageId === languageId);
    const language = store.languages?.find(l => l.id === languageId);
    const modules = store.modules?.filter(m => m.languageId === languageId).sort((a, b) => a.order - b.order);

    const detailedProgress = modules?.map(m => ({
      id: m.id,
      title: m.title,
      order: m.order,
      isCompleted: progress?.completedModuleIds?.includes(m.id) || false
    })) || [];

    res.json({
      language: language?.name,
      completedCount: progress?.completedModuleIds?.length || 0,
      totalModules: modules?.length || 0,
      modules: detailedProgress
    });
  } catch (error) {
    res.status(500).json({ error: error.message });
  }
});

module.exports = router;

