import React, { useState, useEffect } from 'react';
import axios from 'axios';

export default function BookmarksPanel({ moduleId, isOpen, onClose }) {
  const [bookmarks, setBookmarks] = useState([]);
  const [loading, setLoading] = useState(false);
  const [selectedText, setSelectedText] = useState('');

  useEffect(() => {
    if (isOpen && moduleId) {
      fetchBookmarks();
    }
  }, [isOpen, moduleId]);

  const fetchBookmarks = async () => {
    setLoading(true);
    try {
      const response = await axios.get(`/api/bookmarks/module/${moduleId}`);
      setBookmarks(response.data);
    } catch (error) {
      console.error('Error fetching bookmarks:', error);
    } finally {
      setLoading(false);
    }
  };

  const handleAddBookmark = async () => {
    if (!selectedText.trim()) return;

    try {
      const response = await axios.post('/api/bookmarks', {
        moduleId,
        highlightedText: selectedText,
        pageNumber: 0,
        tags: []
      });

      setBookmarks([response.data, ...bookmarks]);
      setSelectedText('');

      // Show success message
      alert('Bookmark added! 📌');
    } catch (error) {
      console.error('Error adding bookmark:', error);
    }
  };

  const handleDeleteBookmark = async (bookmarkId) => {
    try {
      await axios.delete(`/api/bookmarks/${bookmarkId}`);
      setBookmarks(bookmarks.filter(b => b.id !== bookmarkId));
    } catch (error) {
      console.error('Error deleting bookmark:', error);
    }
  };

  if (!isOpen) return null;

  return (
    <div className="fixed right-0 top-0 h-full w-96 bg-white shadow-2xl z-40 flex flex-col animate-slide-in">
      {/* Header */}
      <div className="bg-gradient-to-r from-blue-500 to-blue-600 text-white p-4 flex justify-between items-center">
        <h2 className="text-lg font-bold">📌 Bookmarks</h2>
        <button
          onClick={onClose}
          className="text-2xl font-bold hover:bg-blue-700 w-8 h-8 flex items-center justify-center rounded"
        >
          ✕
        </button>
      </div>

      {/* Add Bookmark Section */}
      <div className="p-4 border-b">
        <label className="block text-sm font-medium text-gray-700 mb-2">Add a highlight</label>
        <div className="flex gap-2">
          <input
            type="text"
            placeholder="Paste highlighted text here..."
            value={selectedText}
            onChange={(e) => setSelectedText(e.target.value)}
            className="flex-1 px-3 py-2 border border-gray-300 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-blue-500"
          />
          <button
            onClick={handleAddBookmark}
            disabled={!selectedText.trim()}
            className="px-3 py-2 bg-blue-500 text-white rounded-lg hover:bg-blue-600 disabled:bg-gray-400 transition text-sm font-medium"
          >
            Add
          </button>
        </div>
      </div>

      {/* Bookmarks List */}
      <div className="flex-1 overflow-y-auto p-4">
        {loading ? (
          <p className="text-center text-gray-500">Loading bookmarks...</p>
        ) : bookmarks.length === 0 ? (
          <p className="text-center text-gray-500 text-sm">No bookmarks yet. Highlight important concepts! ✨</p>
        ) : (
          <div className="space-y-3">
            {bookmarks.map(bookmark => (
              <div key={bookmark.id} className="bg-yellow-50 border-l-4 border-yellow-400 p-3 rounded-r hover:shadow-md transition">
                <p className="text-sm text-gray-800 mb-2">{bookmark.text}</p>
                <div className="flex justify-between items-center">
                  <span className="text-xs text-gray-500">
                    {new Date(bookmark.createdAt).toLocaleDateString()}
                  </span>
                  <button
                    onClick={() => handleDeleteBookmark(bookmark.id)}
                    className="text-xs text-red-500 hover:text-red-700 font-medium"
                  >
                    Delete
                  </button>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>

      <style jsx>{`
        @keyframes slide-in {
          from {
            transform: translateX(100%);
          }
          to {
            transform: translateX(0);
          }
        }
        .animate-slide-in {
          animation: slide-in 0.3s ease-out;
        }
      `}</style>
    </div>
  );
}

