export default function NotesPanel({ moduleId, isOpen, onClose }) {
  const [notes, setNotes] = useState([]);
  const [loading, setLoading] = useState(false);
  const [newNoteTitle, setNewNoteTitle] = useState('');
  const [newNoteContent, setNewNoteContent] = useState('');
  const [editingId, setEditingId] = useState(null);
  const [selectedCategory, setSelectedCategory] = useState('general');

  const categories = ['general', 'important', 'question', 'doubt'];

  useEffect(() => {
    if (isOpen && moduleId) {
      fetchNotes();
    }
  }, [isOpen, moduleId]);

  const fetchNotes = async () => {
    setLoading(true);
    try {
      const response = await axios.get(`/api/notes/module/${moduleId}`);
      setNotes(response.data);
    } catch (error) {
      console.error('Error fetching notes:', error);
    } finally {
      setLoading(false);
    }
  };

  const handleAddNote = async () => {
    if (!newNoteTitle.trim() || !newNoteContent.trim()) {
      alert('Please fill in both title and content');
      return;
    }

    try {
      const response = await axios.post('/api/notes', {
        moduleId,
        title: newNoteTitle,
        content: newNoteContent,
        category: selectedCategory
      });

      setNotes([response.data, ...notes]);
      setNewNoteTitle('');
      setNewNoteContent('');
      alert('Note added! 📝');
    } catch (error) {
      console.error('Error adding note:', error);
    }
  };

  const handleDeleteNote = async (noteId) => {
    if (window.confirm('Delete this note?')) {
      try {
        await axios.delete(`/api/notes/${noteId}`);
        setNotes(notes.filter(n => n.id !== noteId));
      } catch (error) {
        console.error('Error deleting note:', error);
      }
    }
  };

  const handleUpdateNote = async (noteId, updatedContent) => {
    try {
      const response = await axios.put(`/api/notes/${noteId}`, {
        content: updatedContent
      });

      setNotes(notes.map(n => n.id === noteId ? response.data : n));
      setEditingId(null);
    } catch (error) {
      console.error('Error updating note:', error);
    }
  };

  if (!isOpen) return null;

  return (
    <div className="fixed right-0 bottom-0 w-96 h-96 bg-white shadow-2xl z-40 flex flex-col border-t-4 border-purple-500 rounded-t-lg animate-slide-up">
      {/* Header */}
      <div className="bg-gradient-to-r from-purple-500 to-purple-600 text-white p-4 flex justify-between items-center rounded-t-lg">
        <h2 className="text-lg font-bold">📝 My Notes</h2>
        <button
          onClick={onClose}
          className="text-2xl font-bold hover:bg-purple-700 w-8 h-8 flex items-center justify-center rounded"
        >
          ✕
        </button>
      </div>

      {/* Add Note Section */}
      <div className="p-3 border-b bg-gray-50">
        <input
          type="text"
          placeholder="Note title..."
          value={newNoteTitle}
          onChange={(e) => setNewNoteTitle(e.target.value)}
          className="w-full px-2 py-1 border border-gray-300 rounded text-sm mb-2 focus:outline-none focus:ring-2 focus:ring-purple-500"
        />
        <textarea
          placeholder="Note content..."
          value={newNoteContent}
          onChange={(e) => setNewNoteContent(e.target.value)}
          className="w-full px-2 py-1 border border-gray-300 rounded text-sm mb-2 h-20 resize-none focus:outline-none focus:ring-2 focus:ring-purple-500"
        />
        <div className="flex gap-2">
          <select
            value={selectedCategory}
            onChange={(e) => setSelectedCategory(e.target.value)}
            className="flex-1 px-2 py-1 border border-gray-300 rounded text-xs focus:outline-none focus:ring-2 focus:ring-purple-500"
          >
            {categories.map(cat => (
              <option key={cat} value={cat}>{cat}</option>
            ))}
          </select>
          <button
            onClick={handleAddNote}
            className="px-3 py-1 bg-purple-500 text-white rounded hover:bg-purple-600 transition text-xs font-medium"
          >
            Add
          </button>
        </div>
      </div>

      {/* Notes List */}
      <div className="flex-1 overflow-y-auto p-3">
        {loading ? (
          <p className="text-center text-gray-500 text-sm">Loading notes...</p>
        ) : notes.length === 0 ? (
          <p className="text-center text-gray-500 text-xs">No notes yet. Create one above! ✍️</p>
        ) : (
          <div className="space-y-2">
            {notes.map(note => (
              <div
                key={note.id}
                className={`p-2 rounded border-l-4 ${
                  note.category === 'important' ? 'bg-red-50 border-red-400' :
                  note.category === 'question' ? 'bg-blue-50 border-blue-400' :
                  note.category === 'doubt' ? 'bg-orange-50 border-orange-400' :
                  'bg-gray-50 border-gray-400'
                }`}
              >
                {editingId === note.id ? (
                  <div>
                    <textarea
                      value={note.content}
                      onChange={(e) => {
                        const updatedNotes = notes.map(n =>
                          n.id === note.id ? { ...n, content: e.target.value } : n
                        );
                        setNotes(updatedNotes);
                      }}
                      className="w-full px-2 py-1 border border-gray-300 rounded text-xs mb-1 resize-none"
                    />
                    <div className="flex gap-1">
                      <button
                        onClick={() => handleUpdateNote(note.id, note.content)}
                        className="text-xs bg-green-500 text-white px-2 py-1 rounded hover:bg-green-600"
                      >
                        Save
                      </button>
                      <button
                        onClick={() => setEditingId(null)}
                        className="text-xs bg-gray-400 text-white px-2 py-1 rounded hover:bg-gray-500"
                      >
                        Cancel
                      </button>
                    </div>
                  </div>
                ) : (
                  <div>
                    <p className="text-xs font-bold text-gray-800">{note.title}</p>
                    <p className="text-xs text-gray-700 mt-1">{note.content}</p>
                    <div className="flex justify-between items-center mt-1">
                      <span className="text-xs text-gray-500 capitalize">#{note.category}</span>
                      <div className="flex gap-1">
                        <button
                          onClick={() => setEditingId(note.id)}
                          className="text-xs text-blue-600 hover:text-blue-800"
                        >
                          Edit
                        </button>
                        <button
                          onClick={() => handleDeleteNote(note.id)}
                          className="text-xs text-red-600 hover:text-red-800"
                        >
                          Delete
                        </button>
                      </div>
                    </div>
                  </div>
                )}
              </div>
            ))}
          </div>
        )}
      </div>

      <style jsx>{`
        @keyframes slide-up {
          from {
            transform: translateY(100%);
          }
          to {
            transform: translateY(0);
          }
        }
        .animate-slide-up {
          animation: slide-up 0.3s ease-out;
        }
      `}</style>
    </div>
  );
}

import React, { useState } from 'react';
import axios from 'axios';

export default function CodeReviewPanel({ isOpen, onClose }) {
  const [code, setCode] = useState('');
  const [language, setLanguage] = useState('python');
  const [activeTab, setActiveTab] = useState('explain'); // explain, review, debug
  const [error, setError] = useState('');
  const [debugError, setDebugError] = useState('');
  const [result, setResult] = useState(null);
  const [loading, setLoading] = useState(false);

  const languages = ['python', 'java', 'cpp', 'c', 'javascript'];

  const handleExplainCode = async () => {
    if (!code.trim()) {
      setError('Please paste some code first!');
      return;
    }

    setLoading(true);
    setError('');
    try {
      const response = await axios.post('/api/code-review/explain-code', {
        code,
        language
      });

      setResult({
        type: 'explanation',
        explanation: response.data.explanation,
        improvements: response.data.suggested_improvements,
        demoMode: response.data.demo_mode
      });
    } catch (err) {
      setError('Error explaining code. Please try again.');
      console.error('Error:', err);
    } finally {
      setLoading(false);
    }
  };

  const handleCodeReview = async () => {
    if (!code.trim()) {
      setError('Please paste some code first!');
      return;
    }

    setLoading(true);
    setError('');
    try {
      const response = await axios.post('/api/code-review/code-review', {
        code,
        language
      });

      setResult({
        type: 'review',
        review: response.data.review,
        score: response.data.score,
        demoMode: response.data.demo_mode
      });
    } catch (err) {
      setError('Error reviewing code. Please try again.');
      console.error('Error:', err);
    } finally {
      setLoading(false);
    }
  };

  const handleDebugHelp = async () => {
    if (!code.trim() || !debugError.trim()) {
      setError('Please paste code and error message!');
      return;
    }

    setLoading(true);
    setError('');
    try {
      const response = await axios.post('/api/code-review/debug-help', {
        code,
        error: debugError,
        language
      });

      setResult({
        type: 'debug',
        solution: response.data.solution,
        demoMode: response.data.demo_mode
      });
    } catch (err) {
      setError('Error getting debug help. Please try again.');
      console.error('Error:', err);
    } finally {
      setLoading(false);
    }
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
      <div className="bg-white rounded-lg shadow-2xl max-w-4xl w-full max-h-96 overflow-hidden flex flex-col">
        {/* Header */}
        <div className="bg-gradient-to-r from-green-500 to-green-600 text-white p-4 flex justify-between items-center">
          <h2 className="text-2xl font-bold">💻 Code Review & Debug Assistant</h2>
          <button
            onClick={onClose}
            className="text-2xl font-bold hover:bg-green-700 w-8 h-8 flex items-center justify-center rounded"
          >
            ✕
          </button>
        </div>

        {/* Content */}
        <div className="flex flex-1 overflow-hidden">
          {/* Left Side - Input */}
          <div className="flex-1 border-r p-4 overflow-y-auto">
            <div className="space-y-3">
              {/* Language Selection */}
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Language</label>
                <select
                  value={language}
                  onChange={(e) => setLanguage(e.target.value)}
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-green-500 text-sm"
                >
                  {languages.map(lang => (
                    <option key={lang} value={lang}>{lang.toUpperCase()}</option>
                  ))}
                </select>
              </div>

              {/* Code Input */}
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Your Code</label>
                <textarea
                  value={code}
                  onChange={(e) => setCode(e.target.value)}
                  placeholder="Paste your code here..."
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg h-32 font-mono text-xs focus:outline-none focus:ring-2 focus:ring-green-500 resize-none"
                />
              </div>

              {/* Debug Error (only for debug tab) */}
              {activeTab === 'debug' && (
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">Error Message</label>
                  <textarea
                    value={debugError}
                    onChange={(e) => setDebugError(e.target.value)}
                    placeholder="Paste the error message you're getting..."
                    className="w-full px-3 py-2 border border-gray-300 rounded-lg h-16 font-mono text-xs focus:outline-none focus:ring-2 focus:ring-green-500 resize-none"
                  />
                </div>
              )}

              {/* Tabs and Buttons */}
              <div className="space-y-2">
                <div className="flex gap-2 border-b">
                  {[
                    { id: 'explain', label: '📖 Explain', action: handleExplainCode },
                    { id: 'review', label: '🔍 Review', action: handleCodeReview },
                    { id: 'debug', label: '🐛 Debug', action: handleDebugHelp }
                  ].map(tab => (
                    <button
                      key={tab.id}
                      onClick={() => setActiveTab(tab.id)}
                      className={`px-3 py-2 font-medium text-sm transition ${
                        activeTab === tab.id
                          ? 'text-green-600 border-b-2 border-green-600'
                          : 'text-gray-600 hover:text-green-600'
                      }`}
                    >
                      {tab.label}
                    </button>
                  ))}
                </div>

                <button
                  onClick={() => {
                    if (activeTab === 'explain') handleExplainCode();
                    else if (activeTab === 'review') handleCodeReview();
                    else handleDebugHelp();
                  }}
                  disabled={loading}
                  className="w-full px-4 py-2 bg-green-500 text-white rounded-lg hover:bg-green-600 disabled:bg-gray-400 transition font-medium"
                >
                  {loading ? 'Processing...' : `Analyze with ${activeTab.toUpperCase()}`}
                </button>
              </div>

              {error && (
                <div className="bg-red-50 border-l-4 border-red-500 p-3 rounded">
                  <p className="text-red-700 text-sm">{error}</p>
                </div>
              )}
            </div>
          </div>

          {/* Right Side - Result */}
          <div className="flex-1 bg-gray-50 p-4 overflow-y-auto">
            {result ? (
              <div className="space-y-4">
                {result.demoMode && (
                  <div className="bg-yellow-50 border border-yellow-200 p-3 rounded text-sm text-yellow-800">
                    🔔 Demo mode - Add ANTHROPIC_API_KEY for full AI analysis
                  </div>
                )}

                {result.type === 'explanation' && (
                  <>
                    <div>
                      <h3 className="font-bold text-gray-900 mb-2">📖 Explanation</h3>
                      <p className="text-sm text-gray-700 leading-relaxed">{result.explanation}</p>
                    </div>
                    {result.improvements && (
                      <div>
                        <h3 className="font-bold text-gray-900 mb-2">💡 Improvements</h3>
                        <p className="text-sm text-gray-700 whitespace-pre-wrap">{result.improvements}</p>
                      </div>
                    )}
                  </>
                )}

                {result.type === 'review' && (
                  <>
                    <div className="bg-gradient-to-r from-blue-50 to-blue-100 p-3 rounded">
                      <p className="text-xl font-bold text-blue-900">Score: {result.score}/10</p>
                    </div>
                    <div>
                      <h3 className="font-bold text-gray-900 mb-2">🔍 Review</h3>
                      <p className="text-sm text-gray-700 whitespace-pre-wrap">{result.review}</p>
                    </div>
                  </>
                )}

                {result.type === 'debug' && (
                  <div>
                    <h3 className="font-bold text-gray-900 mb-2">🐛 Solution</h3>
                    <p className="text-sm text-gray-700 whitespace-pre-wrap">{result.solution}</p>
                  </div>
                )}
              </div>
            ) : (
              <div className="flex items-center justify-center h-full text-gray-500 text-center">
                <div>
                  <p className="text-lg font-medium mb-2">💻 Code Assistant Ready</p>
                  <p className="text-sm">Paste your code and click a button to start!</p>
                </div>
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

