import os

code_review_bp = Blueprint('code_review', __name__)

# Try to import Anthropic, but handle gracefully if not available
try:
    from anthropic import Anthropic
    client = Anthropic()
    ANTHROPIC_AVAILABLE = True
except ImportError:
    ANTHROPIC_AVAILABLE = False

# Store conversation history
conversation_history = {}

@code_review_bp.route('/explain-code', methods=['POST'])
def explain_code():
    """Explain what a code snippet does"""
    try:
        data = request.json
        code = data.get('code')
        language = data.get('language', 'python')

        if not code:
            return jsonify({'error': 'Code is required'}), 400

        # Check if API key exists
        if not os.getenv('ANTHROPIC_API_KEY'):
            return jsonify({
                'explanation': f"This {language} code demonstrates key programming concepts. (Demo mode - add ANTHROPIC_API_KEY for full explanations)",
                'suggested_improvements': ['Use meaningful variable names', 'Add comments'],
                'demo_mode': True
            })

        if not ANTHROPIC_AVAILABLE:
            return jsonify({'error': 'Anthropic client not available'}), 500

        response = client.messages.create(
            model="claude-3-5-sonnet-20241022",
            max_tokens=1024,
            messages=[{
                "role": "user",
                "content": f"""Explain this {language} code in simple, beginner-friendly terms.
Also suggest 2-3 improvements.

Code:
```{language}
{code}
```

Format your response as:
EXPLANATION: [Simple explanation]
IMPROVEMENTS: [List improvements]"""
            }]
        )

        text = response.content[0].text
        parts = text.split('IMPROVEMENTS:')

        return jsonify({
            'explanation': parts[0].replace('EXPLANATION:', '').strip(),
            'suggested_improvements': parts[1].strip() if len(parts) > 1 else '',
            'demo_mode': False
        })

    except Exception as e:
        return jsonify({'error': str(e)}), 500

@code_review_bp.route('/code-review', methods=['POST'])
def code_review():
    """Detailed code review"""
    try:
        data = request.json
        code = data.get('code')
        language = data.get('language', 'python')

        if not code:
            return jsonify({'error': 'Code is required'}), 400

        if not os.getenv('ANTHROPIC_API_KEY'):
            return jsonify({
                'review': 'Code Review (Demo Mode)\n\nIssues:\n- Consider adding comments\n- Improve variable naming\n- Add error handling\n\nScore: 7/10',
                'score': 7,
                'demo_mode': True
            })

        if not ANTHROPIC_AVAILABLE:
            return jsonify({'error': 'Anthropic client not available'}), 500

        response = client.messages.create(
            model="claude-3-5-sonnet-20241022",
            max_tokens=1500,
            messages=[{
                "role": "user",
                "content": f"""Review this {language} code and provide:
1. Issues (with severity: high/medium/low)
2. Overall score (1-10)
3. Best practices noted

Code:
```{language}
{code}
```"""
            }]
        )

        return jsonify({
            'review': response.content[0].text,
            'score': 8,
            'demo_mode': False
        })

    except Exception as e:
        return jsonify({'error': str(e)}), 500

@code_review_bp.route('/debug-help', methods=['POST'])
def debug_help():
    """Get debugging help for code"""
    try:
        data = request.json
        code = data.get('code')
        error = data.get('error')
        language = data.get('language', 'python')

        if not code or not error:
            return jsonify({'error': 'Code and error message are required'}), 400

        if not os.getenv('ANTHROPIC_API_KEY'):
            return jsonify({
                'diagnosis': 'Common issues could be logic errors or syntax mistakes.',
                'solution': 'Review the error message and check variable types.',
                'prevention_tips': ['Add print statements for debugging', 'Test with different inputs'],
                'demo_mode': True
            })

        if not ANTHROPIC_AVAILABLE:
            return jsonify({'error': 'Anthropic client not available'}), 500

        response = client.messages.create(
