2. How to fix it
3. How to prevent it in future"""
            }]
        )

        return jsonify({
            'solution': response.content[0].text,
            'demo_mode': False
        })

    except Exception as e:
        return jsonify({'error': str(e)}), 500

@code_review_bp.route('/health', methods=['GET'])
def code_review_health():
