      userId,
      activityType, // 'module_completed', 'quiz_taken', 'certificate_earned', etc.
      metadata,
      date: new Date().toISOString(),
      timestamp: Date.now()
    });

    updateStore(store);
  }

  static calculateLeaderboard(limit = 50) {
