{"content": "import React, { useState, useEffect } from 'react';
import axios from 'axios';

export default function WelcomeFlow({ onComplete }) {
  const [stage, setStage] = useState('greeting');
  const [messages, setMessages] = useState([]);
  const [conversation, setConversation] = useState([]);
  const [personality, setPersonality] = useState(null);
  const [goal, setGoal] = useState(null);
  const [userInput, setUserInput] = useState('');
  const [loading, setLoading] = useState(false);
  const [userName, setUserName] = useState('');

  // Initialize welcome on component mount
  useEffect(() => {
    if (stage === 'greeting') {
      const welcomeMessages = [
        {
          speaker: 'bot',
          message: 'Hey there! 👋 Welcome to CodePath!',
          delay: 0
        },
        {
          speaker: 'bot',
          message: "I'm so excited you're here to learn coding!",
          delay: 1
        },
        {
          speaker: 'bot',
          message: "What's your name?",
          delay: 2
        }
      ];
      setConversation(welcomeMessages);
    }
  }, [stage]);

  // Fetch next stage from backend
  const handleNext = async (response) => {
    if (!response?.trim()) return;

    setLoading(true);
    try {
      // Add user's response to conversation
      setConversation(prev => [...prev, {
        speaker: 'user',
        message: response
      }]);

      // Get next stage
      const res = await axios.post('/api/onboarding/next-stage', {
        stage,
        response
      });

      if (res.data.stage === 'complete') {
        // Save onboarding state
        await axios.post('/api/onboarding/save-state', {
          personality,
          goal
        });

        setConversation(prev => [...prev, {
          speaker: 'bot',
          message: res.data.message
        }]);

        setTimeout(() => {
          onComplete({ personality, goal, userName });
        }, 1500);
      } else {
        // Update stage and show next messages
        setStage(res.data.stage);
        setUserInput('');

        // Add bot messages with delays
        res.data.messages.forEach((msg, idx) => {
          setTimeout(() => {
            setConversation(prev => [...prev, {
              speaker: 'bot',
              message: msg
            }]);
          }, idx * 800);
        });
      }
    } catch (error) {
      console.error('Error:', error);
      setConversation(prev => [...prev, {
        speaker: 'bot',
        message: 'Sorry, something went wrong. Please try again!'
      }]);
    }
    setLoading(false);
  };

  const handleGreetingSubmit = () => {
    if (userInput.trim()) {
      setUserName(userInput);
      handleNext(userInput);
    }
  };

  const handlePersonalitySelect = (selected) => {
    setPersonality(selected);
    handleNext(selected);
  };

  const handleGoalSelect = (selected) => {
    setGoal(selected);
    handleNext(selected);
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-purple-900 via-blue-900 to-indigo-900 flex items-center justify-center p-4">
      <div className="bg-white rounded-2xl shadow-2xl max-w-2xl w-full p-8">
        {/* Animated Background */}
        <div className="absolute inset-0 opacity-10 pointer-events-none">
          <div className="absolute top-0 left-0 w-40 h-40 bg-blue-400 rounded-full blur-3xl animate-pulse"></div>
          <div className="absolute bottom-0 right-0 w-40 h-40 bg-purple-400 rounded-full blur-3xl animate-pulse"></div>
        </div>

        {/* Conversation Flow */}
        <div className="space-y-4 mb-8 max-h-96 overflow-y-auto">
          {conversation.map((msg, idx) => (
            <div
              key={idx}
              className={`flex ${msg.speaker === 'bot' ? 'justify-start' : 'justify-end'} animate-fade-in`}
            >
              <div
                className={`max-w-xs px-6 py-3 rounded-lg text-sm ${
                  msg.speaker === 'bot'
                    ? 'bg-gradient-to-r from-blue-100 to-blue-50 text-blue-900 rounded-bl-none'
                    : 'bg-gradient-to-r from-green-400 to-green-500 text-white rounded-br-none'
                }`}
              >
                {msg.message}
              </div>
            </div>
          ))}
          {loading && (
            <div className="flex justify-start">
              <div className="bg-blue-100 text-blue-900 px-6 py-3 rounded-lg rounded-bl-none">
                <div className="flex gap-1">
                  <div className="w-2 h-2 bg-blue-900 rounded-full animate-bounce"></div>
                  <div className="w-2 h-2 bg-blue-900 rounded-full animate-bounce" style={{ animationDelay: '0.1s' }}></div>
                  <div className="w-2 h-2 bg-blue-900 rounded-full animate-bounce" style={{ animationDelay: '0.2s' }}></div>
                </div>
              </div>
            </div>
          )}
        </div>

        {/* Input/Options Area */}
        <div className="space-y-3 mt-8">
          {stage === 'greeting' && (
            <div className="flex gap-2">
              <input
                type="text"
                placeholder="Type your name..."
                value={userInput}
                onChange={(e) => setUserInput(e.target.value)}
                onKeyPress={(e) => {
                  if (e.key === 'Enter') {
                    handleGreetingSubmit();
                  }
                }}
                className="flex-1 px-4 py-3 border-2 border-blue-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                disabled={loading}
              />
              <button
                onClick={handleGreetingSubmit}
                disabled={loading || !userInput.trim()}
                className="px-6 py-3 bg-blue-500 text-white rounded-lg hover:bg-blue-600 disabled:bg-gray-400 transition"
              >
                Next →
              </button>
            </div>
          )}

          {stage === 'personality' && (
            <div className="space-y-3">
              {['Quick & Practical', 'Deep & Theoretical'].map(opt => (
                <button
                  key={opt}
                  onClick={() => handlePersonalitySelect(opt)}
                  disabled={loading}
                  className="w-full px-4 py-3 bg-blue-500 hover:bg-blue-600 text-white rounded-lg transition disabled:bg-gray-400"
                >
                  {opt}
                </button>
              ))}
            </div>
          )}

          {stage === 'goal' && (
            <div className="space-y-3">
              {['Career', 'Interview', 'Hobby', 'College'].map(opt => (
                <button
                  key={opt}
                  onClick={() => handleGoalSelect(opt)}
                  disabled={loading}
                  className="w-full px-4 py-3 bg-green-500 hover:bg-green-600 text-white rounded-lg transition disabled:bg-gray-400"
                >
                  {opt}
                </button>
              ))}
            </div>
          )}

          {stage === 'motivation' && (
            <div className="text-center text-gray-600 text-sm">
              Getting your personalized experience ready...
            </div>
          )}
        </div>

        {/* Progress Indicator */}
        <div className="mt-6 flex justify-center gap-2">
          {['greeting', 'personality', 'goal', 'motivation'].map(s => (
            <div
              key={s}
              className={`h-2 w-8 rounded-full transition-all ${
                ['greeting', 'personality', 'goal', 'motivation'].indexOf(stage) >= ['greeting', 'personality', 'goal', 'motivation'].indexOf(s)
                  ? 'bg-blue-500'
                  : 'bg-gray-300'
              }`}
            ></div>
          ))}
        </div>
      </div>

      <style jsx>{`
        @keyframes fade-in {
          from {
            opacity: 0;
            transform: translateY(10px);
          }
          to {
            opacity: 1;
            transform: translateY(0);
          }
        }
        .animate-fade-in {
          animation: fade-in 0.3s ease-out;
        }
      `}</style>
    </div>
  );
}
