{"content": "import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { useAuth } from '../context/AuthContext';

export default function Dashboard() {
  const { user } = useAuth();
  const [stats, setStats] = useState(null);
  const [loading, setLoading] = useState(true);
  const [selectedLanguage, setSelectedLanguage] = useState(null);

  useEffect(() => {
    const fetchStats = async () => {
      try {
        const response = await axios.get('/api/dashboard/me');
        setStats(response.data);
      } catch (error) {
        console.error('Error fetching dashboard:', error);
      } finally {
        setLoading(false);
      }
    };

    fetchStats();
  }, []);

  if (loading) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-gray-50 to-gray-100 flex items-center justify-center">
        <div className="text-center">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-500 mx-auto mb-4"></div>
          <p className="text-gray-600">Loading your dashboard...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gradient-to-br from-gray-50 to-gray-100 p-8">
      <div className="max-w-6xl mx-auto">
        {/* Header */}
        <div className="mb-12">
          <h1 className="text-4xl font-bold text-gray-900">Welcome back, {user?.name}! 🚀</h1>
          <p className="text-gray-600 mt-2">Here's your learning progress</p>
        </div>

        {/* Stats Grid */}
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 mb-12">
          <StatCard
            title="Languages Learning"
            value={stats?.totalLanguages}
            icon="📚"
            color="blue"
            subtitle="Active courses"
          />
          <StatCard
            title="Modules Completed"
            value={stats?.completedModules}
            icon="✅"
            color="green"
            subtitle="Total progress"
          />
          <StatCard
            title="Average Quiz Score"
            value={`${stats?.averageScore}%`}
            icon="🎯"
            color="purple"
            subtitle="Your performance"
          />
          <StatCard
            title="Certificates Earned"
            value={stats?.certificatesEarned}
            icon="🏆"
            color="yellow"
            subtitle="Achievements"
          />
        </div>

        {/* Current Streak */}
        {stats?.streak > 0 && (
          <div className="bg-gradient-to-r from-orange-500 to-red-500 text-white rounded-lg p-6 mb-12 shadow-lg">
            <h2 className="text-2xl font-bold">🔥 Current Streak: {stats?.streak} days</h2>
            <p className="mt-2 opacity-90">Keep it up! Your consistency is amazing!</p>
          </div>
        )}

        {/* Language Progress Cards */}
        <div>
          <h2 className="text-2xl font-bold text-gray-900 mb-6">Your Languages</h2>
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
            {stats?.progressByLanguage?.map(lang => (
              <LanguageProgressCard 
                key={lang.languageId} 
                language={lang}
                onSelect={() => setSelectedLanguage(lang.languageId)}
              />
            ))}
          </div>
        </div>

        {/* Detailed Module Progress (if language selected) */}
        {selectedLanguage && (
          <ModuleDetailView languageId={selectedLanguage} onClose={() => setSelectedLanguage(null)} />
        )}
      </div>
    </div>
  );
}

function StatCard({ title, value, icon, color, subtitle }) {
  const colorClasses = {
    blue: 'bg-blue-50 border-blue-200 hover:shadow-blue-100',
    green: 'bg-green-50 border-green-200 hover:shadow-green-100',
    purple: 'bg-purple-50 border-purple-200 hover:shadow-purple-100',
    yellow: 'bg-yellow-50 border-yellow-200 hover:shadow-yellow-100'
  };

  return (
    <div className={`${colorClasses[color]} border rounded-lg p-6 shadow-sm hover:shadow-md transition`}>
      <div className="text-3xl mb-3">{icon}</div>
      <p className="text-gray-600 text-xs font-medium uppercase tracking-wider">{title}</p>
      <p className="text-4xl font-bold text-gray-900 mt-2">{value}</p>
      <p className="text-xs text-gray-500 mt-1">{subtitle}</p>
    </div>
  );
}

function LanguageProgressCard({ language, onSelect }) {
  const progressPercent = Math.round((language.completedModules / 10) * 100);
  const statusEmoji = {
    'passed': '✅',
    'ready_for_quiz': '🚀',
    'in_progress': '📚'
  };

  return (
    <div className="bg-white rounded-lg shadow p-6 hover:shadow-lg transition cursor-pointer" onClick={onSelect}>
      <div className="flex justify-between items-start mb-4">
        <h3 className="text-xl font-bold text-gray-900">{language.languageName}</h3>
        <span className="text-2xl">{statusEmoji[language.status] || '🎓'}</span>
      </div>

      <div className="mb-4">
        <div className="flex justify-between items-center mb-2">
          <span className="text-sm font-medium text-gray-600">Progress</span>
          <span className="text-sm font-bold text-gray-900">{language.completedModules}/10</span>
        </div>
        <div className="w-full bg-gray-200 rounded-full h-3">
          <div
            className="bg-gradient-to-r from-blue-500 to-purple-600 h-3 rounded-full transition-all"
            style={{ width: `${progressPercent}%` }}
          ></div>
        </div>
      </div>

      <div className="flex justify-between items-center">
        <span className="text-sm text-gray-600 font-medium">{progressPercent}% Complete</span>
        <span className={`px-3 py-1 rounded-full text-xs font-semibold capitalize ${
          language.status === 'passed' ? 'bg-green-100 text-green-800' :
          language.status === 'ready_for_quiz' ? 'bg-blue-100 text-blue-800' :
          'bg-gray-100 text-gray-800'
        }`}>
          {language.status.replace(/_/g, ' ')}
        </span>
      </div>

      <button className="w-full mt-4 px-4 py-2 bg-gradient-to-r from-blue-500 to-blue-600 text-white rounded-lg hover:shadow-md transition text-sm font-medium">
        View Modules →
      </button>
    </div>
  );
}

function ModuleDetailView({ languageId, onClose }) {
  const [modules, setModules] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchModules = async () => {
      try {
        const response = await axios.get(`/api/dashboard/language/${languageId}`);
        setModules(response.data.modules || []);
      } catch (error) {
        console.error('Error fetching modules:', error);
      } finally {
        setLoading(false);
      }
    };

    fetchModules();
  }, [languageId]);

  return (
    <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
      <div className="bg-white rounded-lg shadow-2xl max-w-2xl w-full max-h-96 overflow-y-auto">
        <div className="sticky top-0 bg-gradient-to-r from-blue-500 to-blue-600 text-white p-6 flex justify-between items-center">
          <h2 className="text-2xl font-bold">Module Progress</h2>
          <button onClick={onClose} className="text-xl">✕</button>
        </div>

        <div className="p-6">
          {loading ? (
            <p className="text-center text-gray-600">Loading modules...</p>
          ) : (
            <div className="space-y-3">
              {modules.map(module => (
                <div key={module.id} className="flex items-center justify-between p-3 bg-gray-50 rounded-lg">
                  <div>
                    <p className="font-semibold text-gray-900">Module {module.order}</p>
                    <p className="text-sm text-gray-600">{module.title}</p>
                  </div>
                  <span className="text-xl">{module.isCompleted ? '✅' : '⭕'}</span>
                </div>
              ))}
            </div>
          )}
        </div>
      </div>
    </div>
  );
}
