{"content": "import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { useAuth } from '../context/AuthContext';

export default function Leaderboard() {
  const { user } = useAuth();
  const [leaderboard, setLeaderboard] = useState([]);
  const [userRank, setUserRank] = useState(null);
  const [loading, setLoading] = useState(true);
  const [filter, setFilter] = useState('all');

  useEffect(() => {
    const fetchData = async () => {
      try {
        const [lbRes, urRes] = await Promise.all([
          axios.get('/api/leaderboard'),
          user ? axios.get('/api/leaderboard/me') : Promise.resolve({ data: null })
        ]);

        setLeaderboard(lbRes.data);
        if (urRes.data) {
          setUserRank(urRes.data);
        }
      } catch (error) {
        console.error('Error fetching leaderboard:', error);
      } finally {
        setLoading(false);
      }
    };

    fetchData();
  }, [user]);

  if (loading) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-gray-50 to-gray-100 flex items-center justify-center">
        <div className="text-center">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-500 mx-auto mb-4"></div>
          <p className="text-gray-600">Loading leaderboard...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gradient-to-br from-gray-50 to-gray-100 p-8">
      <div className="max-w-4xl mx-auto">
        <h1 className="text-4xl font-bold text-gray-900 mb-8">🏆 Global Leaderboard</h1>

        {/* User's Position */}
        {userRank && userRank.rank && (
          <div className="bg-gradient-to-r from-yellow-400 to-yellow-600 text-white rounded-lg p-6 mb-8 shadow-lg hover:shadow-xl transition">
            <div className="flex justify-between items-center">
              <div>
                <p className="text-sm opacity-90">Your Rank</p>
                <p className="text-5xl font-bold">#{userRank.rank}</p>
              </div>
              <div className="text-right">
                <p className="text-sm opacity-90">Your Score</p>
                <p className="text-5xl font-bold">{userRank.entry?.score || 0}</p>
              </div>
              <div className="text-right">
                <p className="text-sm opacity-90">Certificates</p>
                <p className="text-3xl font-bold">{userRank.entry?.certificatesCount || 0}</p>
              </div>
            </div>
          </div>
        )}

        {/* Filter Tabs */}
        <div className="flex gap-4 mb-8">
          <button
            onClick={() => setFilter('all')}
            className={`px-6 py-2 rounded-lg font-medium transition ${
              filter === 'all'
                ? 'bg-blue-500 text-white'
                : 'bg-white text-gray-700 border border-gray-300 hover:border-blue-500'
            }`}
          >
            All Time
          </button>
          <button
            onClick={() => setFilter('month')}
            className={`px-6 py-2 rounded-lg font-medium transition ${
              filter === 'month'
                ? 'bg-blue-500 text-white'
                : 'bg-white text-gray-700 border border-gray-300 hover:border-blue-500'
            }`}
          >
            This Month
          </button>
        </div>

        {/* Top 10 Leaderboard */}
        <div className="space-y-3">
          <h2 className="text-xl font-bold text-gray-900 mb-4">Top 10 Learners</h2>
          {leaderboard.slice(0, 10).map((entry, idx) => (
            <LeaderboardRow
              key={entry.userId}
              rank={idx + 1}
              entry={entry}
              isCurrentUser={entry.userId === user?.id}
            />
          ))}
        </div>

        {/* Full Leaderboard */}
        {leaderboard.length > 10 && (
          <div className="mt-12">
            <h2 className="text-xl font-bold text-gray-900 mb-4">Full Leaderboard (Top 50)</h2>
            <div className="space-y-2 max-h-96 overflow-y-auto bg-white rounded-lg shadow p-4">
              {leaderboard.slice(10, 50).map((entry, idx) => (
                <LeaderboardRow
                  key={entry.userId}
                  rank={idx + 11}
                  entry={entry}
                  isCurrentUser={entry.userId === user?.id}
                  compact={true}
                />
              ))}
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

function LeaderboardRow({ rank, entry, isCurrentUser, compact = false }) {
  const medalEmoji = {
    1: '🥇',
    2: '🥈',
    3: '🥉'
  };

  if (compact) {
    return (
      <div className={`flex items-center justify-between p-2 rounded ${
        isCurrentUser ? 'bg-blue-100' : 'hover:bg-gray-50'
      }`}>
        <div className="flex items-center gap-3 flex-1">
          <span className="text-lg font-bold min-w-12 text-center">
            {medalEmoji[rank] || `#${rank}`}
          </span>
          <span className="font-semibold text-gray-900">{entry.name}</span>
        </div>
        <span className="text-lg font-bold text-gray-900">{entry.score}</span>
      </div>
    );
  }

  return (
    <div className={`rounded-lg p-4 flex items-center justify-between transition ${
      isCurrentUser
        ? 'bg-gradient-to-r from-blue-50 to-blue-100 border-2 border-blue-500 shadow-md'
        : 'bg-white border border-gray-200 hover:shadow-md hover:border-gray-300'
    }`}>
      <div className="flex items-center gap-4">
        <div className="text-4xl min-w-16 text-center">
          {medalEmoji[rank] || `#${rank}`}
        </div>
        <div>
          <p className="font-bold text-gray-900 text-lg">{entry.name}</p>
          <p className="text-sm text-gray-600">
            {entry.certificatesCount} certificates • {entry.averageScore}% avg score • {entry.quizzesTaken} quizzes
          </p>
        </div>
      </div>
      <div className="text-right">
        <p className="text-3xl font-bold text-gray-900">{entry.score}</p>
        <p className="text-xs text-gray-500">Points</p>
      </div>
    </div>
  );
}
